package com.cosmotune.video.downloads

import com.cosmotune.video.model.SubtitleTrack

/** The track a download takes and the label the Downloads page shows ("English", "English (auto-generated)", "none"). */
data class PickedSubtitle(val track: SubtitleTrack?, val label: String)

/** The formats a subtitle track may come in (what the source serves; plan task Y-24, step 2). */
enum class SubtitleFormat {
    VTT, TTML, SRV3, SRV1, SRT, UNKNOWN;

    companion object {
        /** The format of [content]: the content decides when it is recognisable, then the MIME type, then the address's `fmt=`. */
        fun of(mimeType: String?, url: String?, content: String): SubtitleFormat {
            val head = content.removePrefix("﻿").trimStart().take(512)
            return when {
                head.startsWith("WEBVTT") -> VTT
                head.contains("<tt") -> TTML
                head.contains("<timedtext") -> SRV3
                head.contains("<transcript") -> SRV1
                SRT_TIMING.containsMatchIn(head) -> SRT
                else -> byType(mimeType?.lowercase().orEmpty(), url?.substringAfter("fmt=", "")?.substringBefore('&')?.lowercase().orEmpty())
            }
        }

        private fun byType(mime: String, fmt: String): SubtitleFormat = when {
            "vtt" in mime || fmt == "vtt" -> VTT
            "ttml" in mime || fmt == "ttml" -> TTML
            "subrip" in mime || "srt" in mime || fmt == "srt" -> SRT
            fmt == "srv3" -> SRV3
            fmt == "srv1" -> SRV1
            else -> UNKNOWN
        }

        private val SRT_TIMING = Regex("""\d{1,2}:\d{2}:\d{2},\d{3}\s*-->""")
    }
}

/**
 * Subtitles of a download (plan task Y-24, step 2; spec 5.16): which track each video takes, the file name beside the video,
 * and the conversion to WebVTT of what the source may serve (TTML, timed text format 3 and 1, SubRip). Pure: no file, no network.
 */
object SubtitleFiles {
    /** The label of "no subtitles". */
    const val NONE_LABEL = "none"

    private const val AUTO_SUFFIX = " (auto-generated)"

    /**
     * The track a download takes (spec 5.16) and its label:
     * - one video ([pick] has a language tag): that language if the video has it (a manual track first, then an auto-generated
     *   one), else the video's original language, else none;
     * - a batch ([pick] language null): the app's language ([appLanguage]), else the original language, else none;
     * - "each video's original language" (language ""): the original language, else none.
     * [originalLanguage] defaults to the language of the auto-generated track (the source transcribes the spoken language).
     * A regional track ("en-GB") matches its language ("en") after the exact ones.
     */
    fun pick(pick: SubtitlePick, tracks: List<SubtitleTrack>, appLanguage: String, originalLanguage: String? = null): PickedSubtitle {
        if (!pick.enabled || tracks.isEmpty()) return PickedSubtitle(null, NONE_LABEL)
        val original = originalLanguage ?: tracks.firstOrNull { it.autoGenerated }?.language
        val wanted = when (val tag = pick.language) {
            null -> listOfNotNull(appLanguage.takeIf { it.isNotBlank() }, original)
            "" -> listOfNotNull(original)
            else -> listOfNotNull(tag, original)
        }
        for (tag in wanted) {
            val track = find(tracks, tag) ?: continue
            return PickedSubtitle(track, labelOf(track))
        }
        return PickedSubtitle(null, NONE_LABEL)
    }

    /** The subtitle file beside the video: "<name>.<tag>.vtt". */
    fun fileName(baseName: String, languageTag: String): String = "$baseName.$languageTag.vtt"

    /** The label of [track]: its name without the mark, with " (auto-generated)" for a machine track. */
    fun labelOf(track: SubtitleTrack): String {
        val name = track.name.removeSuffix(AUTO_SUFFIX).trim().ifEmpty { track.language }
        return if (track.autoGenerated) name + AUTO_SUFFIX else name
    }

    /** Whether two language tags name the same language: equal ignoring case, or the same primary subtag ("en-GB" and "en"). */
    fun sameLanguage(a: String, b: String): Boolean =
        a.equals(b, ignoreCase = true) || (a.isNotEmpty() && b.isNotEmpty() && primary(a).equals(primary(b), ignoreCase = true))

    private fun primary(tag: String) = tag.substringBefore('-').substringBefore('_')

    private fun find(tracks: List<SubtitleTrack>, tag: String): SubtitleTrack? {
        val manual = tracks.filterNot { it.autoGenerated }
        val auto = tracks.filter { it.autoGenerated }
        return manual.firstOrNull { it.language.equals(tag, ignoreCase = true) }
            ?: manual.firstOrNull { sameLanguage(it.language, tag) }
            ?: auto.firstOrNull { it.language.equals(tag, ignoreCase = true) }
            ?: auto.firstOrNull { sameLanguage(it.language, tag) }
    }

    // ---- To WebVTT -------------------------------------------------------------------------------------------------------

    /**
     * [content] as WebVTT: WebVTT passes through (without a byte-order mark); TTML, timed text format 3 and 1 and SubRip are
     * converted cue by cue (timing, line breaks, entities decoded then escaped for WebVTT; empty cues dropped). [format]
     * UNKNOWN sniffs the content; content that cannot be read becomes an empty WebVTT file.
     */
    fun toVtt(content: String, format: SubtitleFormat): String {
        val text = content.removePrefix("﻿")
        val actual = if (format == SubtitleFormat.UNKNOWN) SubtitleFormat.of(null, null, text) else format
        val cues = when (actual) {
            SubtitleFormat.VTT -> return text
            SubtitleFormat.TTML -> ttml(text)
            SubtitleFormat.SRV3 -> timedText(text, Regex("""<p\b([^>]*)>([\s\S]*?)</p>"""), "t", "d", millis = true)
            SubtitleFormat.SRV1 -> timedText(text, Regex("""<text\b([^>]*)>([\s\S]*?)</text>"""), "start", "dur", millis = false)
            SubtitleFormat.SRT -> srt(text)
            SubtitleFormat.UNKNOWN -> emptyList()
        }
        return buildString {
            append("WEBVTT\n")
            for (cue in cues) append('\n').append(timestamp(cue.startMs)).append(" --> ").append(timestamp(cue.endMs)).append('\n').append(cue.text).append('\n')
        }
    }

    private class Cue(val startMs: Long, val endMs: Long, val text: String)

    private val P = Regex("""<p\b([^>]*?)(/?)>""")
    private val BR = Regex("""<br\s*/?>""", RegexOption.IGNORE_CASE)
    private val TAG = Regex("""<[^>]*>""")
    private val SPACE = Regex("""\s+""")

    private fun ttml(text: String): List<Cue> {
        val root = Regex("""<tt\b[^>]*>""").find(text)?.value.orEmpty()
        val tickRate = attribute(root, "ttp:tickRate")?.toDoubleOrNull()
        val frameRate = attribute(root, "ttp:frameRate")?.toDoubleOrNull() ?: 30.0
        val cues = mutableListOf<Cue>()
        var from = 0
        while (true) {
            val open = P.find(text, from) ?: break
            if (open.groupValues[2] == "/") { from = open.range.last + 1; continue }
            val close = text.indexOf("</p>", open.range.last + 1).takeIf { it >= 0 } ?: break
            val attrs = open.groupValues[1]
            val inner = text.substring(open.range.last + 1, close)
            from = close + 4
            val begin = attribute(attrs, "begin")?.let { ttmlTime(it, tickRate, frameRate) } ?: continue
            val end = attribute(attrs, "end")?.let { ttmlTime(it, tickRate, frameRate) }
                ?: attribute(attrs, "dur")?.let { ttmlTime(it, tickRate, frameRate) }?.plus(begin)
                ?: continue
            cueOf(begin, end, inner)?.let(cues::add)
        }
        return cues
    }

    private fun timedText(text: String, element: Regex, startName: String, durationName: String, millis: Boolean): List<Cue> =
        element.findAll(text).mapNotNull { m ->
            val attrs = m.groupValues[1]
            val start = attribute(attrs, startName)?.toDoubleOrNull() ?: return@mapNotNull null
            val duration = attribute(attrs, durationName)?.toDoubleOrNull() ?: 0.0
            val scale = if (millis) 1.0 else 1000.0
            cueOf((start * scale).toLong(), ((start + duration) * scale).toLong(), m.groupValues[2])
        }.toList()

    /** A cue from markup: white space collapsed, `<br>` as a line break, other tags dropped, entities decoded, lines trimmed. */
    private fun cueOf(startMs: Long, endMs: Long, markup: String): Cue? {
        val lines = SPACE.replace(markup, " ").replace(BR, "\n").replace(TAG, "")
            .let(::decodeEntities).split('\n').map { it.trim() }.filter { it.isNotEmpty() }
        if (lines.isEmpty() || endMs < startMs) return null
        return Cue(startMs, endMs, lines.joinToString("\n") { escape(it) })
    }

    private val SRT_LINE = Regex("""(\d{1,2}):(\d{2}):(\d{2})[,.](\d{1,3})\s*-->\s*(\d{1,2}):(\d{2}):(\d{2})[,.](\d{1,3})""")
    private val SRT_KEPT_TAG = Regex("""&lt;(/?)(i|b|u)&gt;""")

    private fun srt(text: String): List<Cue> {
        val cues = mutableListOf<Cue>()
        for (block in text.replace("\r\n", "\n").replace('\r', '\n').split(Regex("\n\\s*\n"))) {
            val lines = block.split('\n')
            val at = lines.indexOfFirst { SRT_LINE.containsMatchIn(it) }
            if (at < 0) continue
            val g = SRT_LINE.find(lines[at])!!.groupValues
            fun ms(h: String, m: String, s: String, f: String) = ((h.toLong() * 60 + m.toLong()) * 60 + s.toLong()) * 1000 + f.padEnd(3, '0').toLong()
            val body = lines.drop(at + 1).map { it.trim() }.filter { it.isNotEmpty() }
                .map { line -> SRT_KEPT_TAG.replace(escape(line.replace(Regex("""</?font[^>]*>""", RegexOption.IGNORE_CASE), ""))) { "<${it.groupValues[1]}${it.groupValues[2]}>" } }
            if (body.isEmpty()) continue
            cues += Cue(ms(g[1], g[2], g[3], g[4]), ms(g[5], g[6], g[7], g[8]), body.joinToString("\n"))
        }
        return cues
    }

    /** An attribute's value in [attrs] (double or single quotes), or null. */
    private fun attribute(attrs: String, name: String): String? =
        Regex("""(?:^|\s)${Regex.escape(name)}\s*=\s*(?:"([^"]*)"|'([^']*)')""").find(attrs)?.let { m -> m.groupValues[1].ifEmpty { m.groupValues[2] } }

    /** A TTML time: clock time ("00:00:01.500", "00:00:01:12" with frames) or an offset ("1.5s", "1500ms", "2m", "90f", "15000000t"). */
    private fun ttmlTime(value: String, tickRate: Double?, frameRate: Double): Long? {
        val v = value.trim()
        val clock = Regex("""^(\d+):(\d{2}):(\d{2})(?:\.(\d+))?(?::(\d+(?:\.\d+)?))?$""").find(v)
        if (clock != null) {
            val g = clock.groupValues
            val fraction = if (g[4].isEmpty()) 0.0 else "0.${g[4]}".toDouble()
            val frames = g[5].toDoubleOrNull()?.div(frameRate) ?: 0.0
            return ((g[1].toLong() * 3600 + g[2].toLong() * 60 + g[3].toLong() + fraction + frames) * 1000).roundToLong()
        }
        val offset = Regex("""^(\d+(?:\.\d+)?)(h|ms|m|s|f|t)$""").find(v) ?: return null
        val n = offset.groupValues[1].toDouble()
        val seconds = when (offset.groupValues[2]) {
            "h" -> n * 3600
            "m" -> n * 60
            "s" -> n
            "ms" -> n / 1000
            "f" -> n / frameRate
            else -> n / (tickRate ?: 10_000_000.0)
        }
        return (seconds * 1000).roundToLong()
    }

    private fun Double.roundToLong(): Long = kotlin.math.round(this).toLong()

    /** "hh:mm:ss.mmm", as WebVTT writes cue times. */
    private fun timestamp(ms: Long): String {
        val total = ms.coerceAtLeast(0)
        val h = total / 3_600_000
        val m = total / 60_000 % 60
        val s = total / 1000 % 60
        val f = total % 1000
        return "${pad(h, 2)}:${pad(m, 2)}:${pad(s, 2)}.${pad(f, 3)}"
    }

    private fun pad(n: Long, width: Int) = n.toString().padStart(width, '0')

    /** The XML entities and numeric references of [text], decoded. */
    private fun decodeEntities(text: String): String =
        Regex("""&(#[xX][0-9a-fA-F]+|#\d+|amp|lt|gt|quot|apos|nbsp);""").replace(text) { m ->
            when (val name = m.groupValues[1]) {
                "amp" -> "&"
                "lt" -> "<"
                "gt" -> ">"
                "quot" -> "\""
                "apos" -> "'"
                "nbsp" -> " "
                else -> {
                    val code = if (name[1] == 'x' || name[1] == 'X') name.substring(2).toIntOrNull(16) else name.substring(1).toIntOrNull()
                    if (code == null || code < 0 || code > 0x10FFFF) m.value else codePoint(code)
                }
            }
        }

    private fun codePoint(code: Int): String {
        if (code < 0x10000) return code.toChar().toString()
        val c = code - 0x10000
        return charArrayOf(((c shr 10) + 0xD800).toChar(), ((c and 0x3FF) + 0xDC00).toChar()).concatToString()
    }

    /** Text made safe inside a WebVTT cue: `&`, `<` and `>` as entities (which also keeps "-->" out of the text). */
    private fun escape(text: String): String = text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
}
